"use client"

import { createContext, useContext, useReducer, useEffect, type ReactNode, type Dispatch } from "react"
import type { AuthUser } from "@/lib/types"
import { demoUsers } from "@/lib/data/users"
import { useToast } from "@/hooks/use-toast"

// Creamos un mock inicial para pb
const createPbClient = () => {
  if (typeof window === 'undefined') return null
  
  try {
    // Intentar importar PocketBase dinámicamente
    const PocketBase = require('pocketbase').default
    const POCKETBASE_URL = process.env.NEXT_PUBLIC_POCKETBASE_URL || 'http://127.0.0.1:8090'
    const pb = new PocketBase(POCKETBASE_URL)
    pb.autoCancellation(false)
    return pb
  } catch (error) {
    console.warn('No se pudo crear cliente PocketBase:', error)
    return null
  }
}

interface AuthState {
  user: AuthUser | null
  is_authenticated: boolean
  is_loading: boolean
}

type AuthAction =
  | { type: "LOGIN"; payload: AuthUser }
  | { type: "LOGOUT" }
  | { type: "SET_LOADING"; payload: boolean }
  | { type: "LOAD_FROM_STORAGE"; payload: AuthUser | null }

const initialState: AuthState = {
  user: null,
  is_authenticated: false,
  is_loading: true,
}

function authReducer(state: AuthState, action: AuthAction): AuthState {
  switch (action.type) {
    case "LOGIN":
      return { ...state, user: action.payload, is_authenticated: true, is_loading: false }
    case "LOGOUT":
      return { ...state, user: null, is_authenticated: false, is_loading: false }
    case "SET_LOADING":
      return { ...state, is_loading: action.payload }
    case "LOAD_FROM_STORAGE":
      return {
        ...state,
        user: action.payload,
        is_authenticated: !!action.payload,
        is_loading: false,
      }
    default:
      return state
  }
}

const AuthStateContext = createContext<AuthState | null>(null)
const AuthDispatchContext = createContext<Dispatch<AuthAction> | null>(null)

export function AuthProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(authReducer, initialState)
  const { toast } = useToast()

  useEffect(() => {
    const loadSession = async () => {
      try {
        // Primero intentar con PocketBase si está disponible
        const pb = createPbClient()
        if (pb?.authStore?.isValid) {
          try {
            await pb.collection('users').authRefresh()
            const userModel = pb.authStore.model
            if (userModel) {
              const authUser: AuthUser = {
                id: userModel.id,
                name: userModel.name,
                email: userModel.email,
                role: userModel.role,
                points: userModel.points || 250,
              }
              dispatch({ type: "LOAD_FROM_STORAGE", payload: authUser })
              return
            }
          } catch (pbError) {
            console.warn('Sesión de PocketBase expirada:', pbError)
            pb.authStore.clear()
          }
        }

        // Fallback a localStorage
        const savedUser = localStorage.getItem("imperial_auth_user")
        if (savedUser) {
          try {
            const user = JSON.parse(savedUser)
            dispatch({ type: "LOAD_FROM_STORAGE", payload: user })
          } catch {
            dispatch({ type: "LOAD_FROM_STORAGE", payload: null })
          }
        } else {
          dispatch({ type: "SET_LOADING", payload: false })
        }
      } catch (error) {
        console.error('Error cargando sesión:', error)
        dispatch({ type: "SET_LOADING", payload: false })
      }
    }

    loadSession()
  }, [])

  useEffect(() => {
    if (state.user) {
      localStorage.setItem("imperial_auth_user", JSON.stringify(state.user))
    } else if (!state.is_loading) {
      localStorage.removeItem("imperial_auth_user")
    }
  }, [state.user, state.is_loading])

  return (
    <AuthStateContext.Provider value={state}>
      <AuthDispatchContext.Provider value={dispatch}>{children}</AuthDispatchContext.Provider>
    </AuthStateContext.Provider>
  )
}

export function useAuthState() {
  const context = useContext(AuthStateContext)
  if (!context) {
    throw new Error("useAuthState debe usarse dentro de AuthProvider")
  }
  return context
}

export function useAuthDispatch() {
  const context = useContext(AuthDispatchContext)
  if (!context) {
    throw new Error("useAuthDispatch debe usarse dentro de AuthProvider")
  }
  return context
}

export function useAuth() {
  const state = useAuthState()
  const dispatch = useAuthDispatch()
  const { toast } = useToast()

  const login = async (email: string, password: string): Promise<{ success: boolean; error?: string }> => {
    try {
      dispatch({ type: "SET_LOADING", payload: true })

      // Primero intentar con PocketBase
      try {
        const pb = createPbClient()
        if (pb) {
          const authData = await pb.collection('users').authWithPassword(email, password)
          
          const authUser: AuthUser = {
            id: authData.record.id,
            name: authData.record.name,
            email: authData.record.email,
            role: authData.record.role,
            points: authData.record.points || 250,
          }
          
          dispatch({ type: "LOGIN", payload: authUser })
          toast({
            title: "Inicio de sesión exitoso",
            description: `Bienvenido ${authData.record.name}`,
          })
          return { success: true }
        }
      } catch (pbError: any) {
        console.warn('Autenticación con PocketBase falló, probando usuarios demo:', pbError)
      }

      // Fallback a usuarios demo
      const user = demoUsers.find((u) => u.email === email && u.password === password)
      if (user) {
        const authUser: AuthUser = {
          id: user.id,
          name: user.name,
          email: user.email,
          role: user.role,
          points: user.points,
        }
        dispatch({ type: "LOGIN", payload: authUser })
        toast({
          title: "Modo demo activado",
          description: `Bienvenido ${user.name} (modo demo)`,
        })
        return { success: true }
      }
      
      return { 
        success: false, 
        error: "Correo o contraseña incorrectos" 
      }
    } catch (err: any) {
      console.error('Error en login:', err)
      return { 
        success: false, 
        error: "Ocurrió un error durante el inicio de sesión" 
      }
    } finally {
      dispatch({ type: "SET_LOADING", payload: false })
    }
  }

  const logout = () => {
    // Intentar limpiar PocketBase
    try {
      const pb = createPbClient()
      if (pb) pb.authStore.clear()
    } catch (error) {
      console.warn('Error limpiando PocketBase:', error)
    }
    
    // Limpiar estado local
    dispatch({ type: "LOGOUT" })
    
    toast({
      title: "Sesión cerrada",
      description: "Has cerrado sesión exitosamente",
    })
  }

  const register = async (
    name: string, 
    email: string, 
    password: string, 
    phone?: string
  ): Promise<{ success: boolean; error?: string }> => {
    try {
      // Intentar registro con PocketBase
      try {
        const pb = createPbClient()
        if (pb) {
          const userData = {
            name,
            email,
            password,
            passwordConfirm: password,
            role: 'customer',
            points: 250,
            phone: phone || '',
          }

          await pb.collection('users').create(userData)
          
          // Autenticar después del registro
          return await login(email, password)
        }
      } catch (pbError: any) {
        console.warn('Registro con PocketBase falló, creando usuario local:', pbError)
      }

      // Fallback a usuario local
      const newUser: AuthUser = {
        id: `user-${Date.now()}`,
        name,
        email,
        role: 'customer',
        points: 250,
      }
      
      dispatch({ type: "LOGIN", payload: newUser })
      return { success: true }
    } catch (error: any) {
      console.error('Error en registro:', error)
      return { 
        success: false, 
        error: "El registro falló" 
      }
    }
  }

  return { 
    user: state.user, 
    is_authenticated: state.is_authenticated, 
    is_loading: state.is_loading, 
    login, 
    logout, 
    register 
  }
}